test('invoiceTotals calculates discount based on tier default', () => {
  const invoice = createInvoice({
    customerId: 'C-001', // gold tier (5%)
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 100, discountPercent: undefined }],
  }).value;
  const totals = invoiceTotals(invoice);
  // DES-HOUR: 100 * 8500 = 850000 cents (€8500)
  // discount: 850000 * 5 / 100 = 42500 cents (€425)
  // DES-HOUR vatRate: 21, VAT = (850000 - 42500) * 21 / 100 = 807500 * 21 / 100 = 169575
  assert.equal(totals.subtotal, 850000);
  assert.equal(totals.discount, 42500);
  assert.equal(totals.vat, 169575);
  assert.equal(totals.total, 850000 - 42500 + 169575);
});

test('invoiceTotals with multiple lines and tier discounts', () => {
  const invoice = createInvoice({
    customerId: 'C-003', // silver tier (2.5%)
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10 }, // gets 2.5%, vatRate 21
      { sku: 'DEV-HOUR', qty: 5, discountPercent: 10 }, // explicit 10%, vatRate 21
    ],
  }).value;
  const totals = invoiceTotals(invoice);
  // Line 1: 10 * 8500 = 85000, discount = 85000 * 2.5 / 100 = 2125, after discount = 82875, VAT = 82875 * 21 / 100 = 17403.75 → 17404
  // Line 2: 5 * 9500 = 47500, discount = 47500 * 10 / 100 = 4750, after discount = 42750, VAT = 42750 * 21 / 100 = 8977.5 → 8978
  // Subtotal: 85000 + 47500 = 132500
  // Total discount: 2125 + 4750 = 6875
  // Total VAT: 17404 + 8978 = 26382
  // Total: 132500 - 6875 + 26382 = 152007
  assert.equal(totals.subtotal, 132500);
  assert.equal(totals.discount, 6875);
  assert.equal(totals.vat, 26382);
  assert.equal(totals.total, 152007);
});

